import{_ as e,o as i,c as a,a2 as o}from"./chunks/framework.dMg474VA.js";const g=JSON.parse('{"title":"Distributed Counter Semantics & Rate-Limiting Guarantees","description":"","frontmatter":{},"headers":[],"relativePath":"semantics.md","filePath":"semantics.md"}'),n={name:"semantics.md"};function r(l,t,s,c,d,u){return i(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="distributed-counter-semantics-rate-limiting-guarantees" tabindex="-1">Distributed Counter Semantics &amp; Rate-Limiting Guarantees <a class="header-anchor" href="#distributed-counter-semantics-rate-limiting-guarantees" aria-label="Permalink to &quot;Distributed Counter Semantics &amp; Rate-Limiting Guarantees&quot;">​</a></h1><p>This document establishes the executable architectural contract and formal semantics for the Rate-Limit Gateway (rlgw) counter engine across in-memory and distributed backends.</p><hr><h2 id="_1-linearizability-specification" tabindex="-1">1. Linearizability Specification <a class="header-anchor" href="#_1-linearizability-specification" aria-label="Permalink to &quot;1. Linearizability Specification&quot;">​</a></h2><p>For any given counter key $K$, the admission decision function <code>Decide(ctx, key, spec, cost, now)</code> is <strong>strictly linearizable</strong> with respect to real monotonic time when executed against a single authoritative shard (in-memory partition or Redis Cluster hash slot):</p><ol><li><strong>Total Order</strong>: All operations on key $K$ are serialized in a discrete order $op_1, op_2, \\dots, op_n$.</li><li><strong>Real-Time Precedence</strong>: If $op_1$ completes before $op_2$ is invoked, $op_2$ observes state after $op_1$.</li><li><strong>No Phantom Admittance</strong>: If request $R$ is denied because cumulative cost exceeds limit $L$, no subsequent request can be admitted within the same window unless tokens are refilled or refunded.</li></ol><hr><h2 id="_2-multi-instance-guarantees-n-gateway-nodes" tabindex="-1">2. Multi-Instance Guarantees ($N$ Gateway Nodes) <a class="header-anchor" href="#_2-multi-instance-guarantees-n-gateway-nodes" aria-label="Permalink to &quot;2. Multi-Instance Guarantees ($N$ Gateway Nodes)&quot;">​</a></h2><p>When $N$ independent gateway instances share a centralized counter data plane (Redis Cluster in Set 5):</p><ul><li><strong>Exact Mode</strong>: All gateway instances issue atomic commands (<code>Decide</code> via Lua script). The system behaves identically to a single unified gateway with zero under- or over-counting. Latency budget: network RTT + ~15 µs Redis execution.</li><li><strong>Local-Batched Lease Approximation Mode (Set 4)</strong>: Gateways pre-allocate token slices of size $B = \\lfloor \\text{limit} / 2N \\rfloor$. <ul><li>Maximum over-admission error bound across all nodes: $$\\Delta \\le N \\times B \\le \\frac{\\text{limit}}{2}$$</li><li>Heartbeat sync runs every $\\tau$ seconds; leases expire automatically if a gateway node crashes, preventing permanent quota leaks.</li></ul></li></ul><hr><h2 id="_3-algorithm-burst-semantics-table-f23" tabindex="-1">3. Algorithm Burst Semantics Table (F23) <a class="header-anchor" href="#_3-algorithm-burst-semantics-table-f23" aria-label="Permalink to &quot;3. Algorithm Burst Semantics Table (F23)&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Algorithm</th><th style="text-align:left;">State Variable</th><th style="text-align:left;">Semantics of <code>Burst</code> Parameter</th><th style="text-align:left;">Max Requests Admitted in Window $W$</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Token Bucket</strong></td><td style="text-align:left;"><code>maxTokens = burst * 1e9</code></td><td style="text-align:left;">Max token reservoir. Dictates the maximum instantaneous spike allowed from cold/idle state.</td><td style="text-align:left;">$\\text{limit} + \\text{burst}$</td></tr><tr><td style="text-align:left;"><strong>Leaky Bucket</strong></td><td style="text-align:left;"><code>capacity = burst * 1e9</code></td><td style="text-align:left;">Maximum queue depth before overflow. Incoming water drains at rate $\\text{limit} / W$.</td><td style="text-align:left;">$\\text{burst}$ (concurrency cap)</td></tr><tr><td style="text-align:left;"><strong>Fixed Window</strong></td><td style="text-align:left;"><code>capacity = limit</code></td><td style="text-align:left;">Counter ceiling for aligned window interval $[\\lfloor t/W \\rfloor W, \\lfloor t/W \\rfloor W + W)$.</td><td style="text-align:left;">$2 \\times \\text{limit}$ (straddling boundary)</td></tr><tr><td style="text-align:left;"><strong>Sliding Window Log</strong></td><td style="text-align:left;"><code>HardCap = limit</code></td><td style="text-align:left;">Exact timestamp ring buffer capacity. Hard cap on admissions within any sliding window of duration $W$.</td><td style="text-align:left;">$\\text{limit}$ (strictly conserved)</td></tr><tr><td style="text-align:left;"><strong>Sliding Window Counter</strong></td><td style="text-align:left;"><code>limit = limit * 1e9</code></td><td style="text-align:left;">Weighted approximation ceiling: $\\text{count} = \\text{prev} \\times \\frac{W - \\Delta t}{W} + \\text{curr}$.</td><td style="text-align:left;">$1.0\\times \\text{ to } 1.5\\times \\text{limit}$ (worst-case skew)</td></tr><tr><td style="text-align:left;"><strong>GCRA</strong></td><td style="text-align:left;">$\\tau = \\text{burst} \\times \\frac{W}{\\text{limit}}$</td><td style="text-align:left;">Burst tolerance $\\tau$. Maximum time ahead of Theoretical Arrival Time ($TAT$) allowed before cell rejection.</td><td style="text-align:left;">$\\text{limit} + \\text{burst}$</td></tr></tbody></table><hr><h2 id="_4-sliding-window-counter-approximation-error-bound-f20" tabindex="-1">4. Sliding Window Counter Approximation Error Bound (F20) <a class="header-anchor" href="#_4-sliding-window-counter-approximation-error-bound-f20" aria-label="Permalink to &quot;4. Sliding Window Counter Approximation Error Bound (F20)&quot;">​</a></h2><p>Let $W$ be window duration, $C_{prev}$ the request count in previous window, $C_{curr}$ the count in current window, and $\\Delta t = t \\pmod W$. The estimated count is: $$\\hat{N}(t) = C_{prev} \\cdot \\left( \\frac{W - \\Delta t}{W} \\right) + C_{curr}$$</p><ul><li><strong>Uniform Traffic</strong>: When arrivals follow a Poisson or uniform distribution, expected error is mathematically zero: $$\\mathbb{E}[\\hat{N}(t) - N_{true}(t)] = 0$$</li><li><strong>Adversarial Worst-Case</strong>: If all $C_{prev}$ requests occurred in the final nanosecond of the previous window, the actual count in $(t - W, t]$ is $C_{prev} + C_{curr}$. The estimation error is: $$\\text{Error} = (C_{prev} + C_{curr}) - \\hat{N}(t) = C_{prev} \\cdot \\frac{\\Delta t}{W} \\le C_{prev}$$ Since $C_{prev} \\le L$ and $C_{curr} \\le L \\frac{\\Delta t}{W}$, total admitted traffic over any interval $W$ is strictly bounded by: $$N_{\\text{max}} \\le 1.5 \\times \\text{Limit}$$ This 1.5x bound is proven empirically in the 100,000 schedule property tests (<code>oracle_test.go</code>).</li></ul><hr><h2 id="_5-clock-skew-tolerance-recovery-f29" tabindex="-1">5. Clock-Skew Tolerance &amp; Recovery (F29) <a class="header-anchor" href="#_5-clock-skew-tolerance-recovery-f29" aria-label="Permalink to &quot;5. Clock-Skew Tolerance &amp; Recovery (F29)&quot;">​</a></h2><p>To insulate against NTP step adjustments, container VM freezes, and virtualization time-drifts:</p><ol><li><strong>Monotonic Progression</strong>: All time differences are calculated against monotonically increasing nanosecond clocks (<code>clock.HighResClock</code>).</li><li><strong>Backward Skew Clamp</strong>: If an incoming timestamp $t_{now} &lt; t_{lastSeen}$, the <code>SkewGuard</code> clamps $t_{effective} = t_{lastSeen}$ and increments <code>ClampedEvents</code>.</li><li><strong>No Negative Refills</strong>: Token buckets and leaky buckets will <strong>never</strong> drain or refill negatively upon a backward clock jump.</li><li><strong>No Lockouts</strong>: Rejections calculate <code>RetryAfter</code> strictly positive ($\\ge 1 \\text{ ns}$), guaranteeing the gateway never issues negative wait durations or permanent deadlocks to callers.</li></ol><hr><h2 id="_6-refund-semantics" tabindex="-1">6. Refund Semantics <a class="header-anchor" href="#_6-refund-semantics" aria-label="Permalink to &quot;6. Refund Semantics&quot;">​</a></h2><p>A rate-limiting gateway encounters downstream failure modes (upstream timeouts, circuit breaker trip, client disconnects before upstream dispatch) where admitted quota should not penalize the caller.</p><ol><li><strong>Idempotent Restoration</strong>: <code>Refund(key, spec, cost, now)</code> restores up to <code>cost</code> units back to the counter without exceeding the configured ceiling or capacity.</li><li><strong>Algorithm Restorations</strong>: <ul><li><strong>Token Bucket</strong>: $\\text{tokens} = \\min(\\text{capacity}, \\text{tokens} + \\text{cost})$.</li><li><strong>Leaky Bucket</strong>: $\\text{level} = \\max(0, \\text{level} - \\text{cost})$.</li><li><strong>Fixed Window</strong>: $\\text{count} = \\max(0, \\text{count} - \\text{cost})$.</li><li><strong>Sliding Window Log</strong>: Removes the most recently appended entries up to <code>cost</code>.</li><li><strong>Sliding Window Counter</strong>: $\\text{currCount} = \\max(0, \\text{currCount} - \\text{cost})$.</li><li><strong>GCRA</strong>: $\\text{TAT} = \\max(0, \\text{TAT} - \\text{cost} \\times I)$ where $I = 1000 / \\text{ratePerSec}$.</li></ul></li></ol><hr><h2 id="_7-multi-policy-semantics-two-phase-decide" tabindex="-1">7. Multi-Policy Semantics (Two-Phase Decide) <a class="header-anchor" href="#_7-multi-policy-semantics-two-phase-decide" aria-label="Permalink to &quot;7. Multi-Policy Semantics (Two-Phase Decide)&quot;">​</a></h2><p>When multiple policies match an incoming request (e.g. global IP throttle + route limit + tenant quota):</p><ol><li><strong>Most Restrictive Wins</strong>: The request is admitted if and only if <strong>all</strong> matching policies permit admission.</li><li><strong>Atomic Two-Phase Decide</strong>: <ul><li><strong>Phase 1 (Peek)</strong>: Every matching policy is evaluated via <code>peek(key, spec, now)</code>. No state mutation occurs.</li><li>If any policy rejects, the request is immediately rejected with the rejection headers and body of the most restrictive policy. Counters for all other policies remain completely untouched.</li><li><strong>Phase 2 (Commit)</strong>: If all matching policies allow the request, each policy is sequentially committed via <code>commit(key, spec, cost, now)</code>.</li><li><strong>Rollback on Race</strong>: If a concurrent request consumes quota between Phase 1 and Phase 2 causing a later policy commit to fail, all earlier committed policies in the chain are refunded immediately via <code>refund(...)</code>.</li></ul></li><li><strong>Terminal Deny</strong>: Policies flagged with <code>terminalDeny: true</code> short-circuit any further policy evaluation immediately upon denial.</li></ol>',29)])])}const h=e(n,[["render",r]]);export{g as __pageData,h as default};
